'use strict';
/*
 * Server-side translations for messages people read: API error messages, in-app notifications
 * and SMS. Dictionaries are keyed by the English text (src/i18n/<lang>.json), generated by
 * scripts/i18n-extract-server.js and translated like the app strings. Text with live values
 * (names, amounts) falls back to English when it has no exact match.
 */
const fs = require('fs');
const path = require('path');
const LANGS = ['pcm', 'yo', 'ha', 'ig'];
const dicts = {};
function dict(lang) {
  if (!LANGS.includes(lang)) return null;
  if (!dicts[lang]) { try { dicts[lang] = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'i18n', lang + '.json'), 'utf8')); } catch (e) { dicts[lang] = {}; } }
  return dicts[lang];
}
function tr(lang, text) {
  if (!text || !lang || lang === 'en') return text;
  const d = dict(lang); if (!d) return text;
  const S = require('./settings');
  const ov = S.get('content.i18n.' + lang, {}) || {};
  return ov['server:' + text] || d[text] || text;
}
module.exports = { tr, LANGS };
